<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: #f4f6f8;
      color: #1f2933;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 24px;
    }

    .app {
      width: min(920px, 100%);
      margin: 0 auto;
    }

    h1,
    h2 {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 20px;
    }

    .panel {
      margin-bottom: 20px;
      padding: 20px;
      background: #fff;
      border: 1px solid #d9e0e7;
      border-radius: 10px;
      box-shadow: 0 2px 8px rgba(31, 41, 51, 0.05);
    }

    .form-grid,
    .filter-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .field {
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .field.full {
      grid-column: 1 / -1;
    }

    label {
      font-size: 0.9rem;
      font-weight: 650;
    }

    input,
    select,
    button {
      min-height: 42px;
      font: inherit;
    }

    input,
    select {
      width: 100%;
      padding: 9px 11px;
      color: #1f2933;
      background: #fff;
      border: 1px solid #b8c2cc;
      border-radius: 6px;
    }

    input:focus,
    select:focus,
    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.2);
      border-color: #2563eb;
    }

    #add-expense {
      padding: 10px 18px;
      color: #fff;
      font-weight: 700;
      background: #2563eb;
      border: 0;
      border-radius: 6px;
      cursor: pointer;
    }

    #add-expense:hover {
      background: #1d4ed8;
    }

    #form-error {
      min-height: 1.4em;
      margin: 10px 0 0;
      color: #b42318;
      font-weight: 650;
    }

    .summary {
      display: grid;
      grid-template-columns: minmax(180px, 1.2fr) repeat(4, minmax(120px, 1fr));
      gap: 10px;
    }

    .summary-item {
      padding: 13px;
      background: #f7f9fb;
      border: 1px solid #d9e0e7;
      border-radius: 7px;
    }

    .summary-label {
      display: block;
      margin-bottom: 4px;
      color: #52606d;
      font-size: 0.82rem;
      text-transform: capitalize;
    }

    #total,
    .cat-total {
      font-size: 1.12rem;
      font-weight: 750;
    }

    .list-header,
    .expense {
      display: grid;
      grid-template-columns: 1fr 1fr 1.1fr 2fr auto;
      gap: 12px;
      align-items: center;
    }

    .list-header {
      padding: 0 12px 9px;
      color: #52606d;
      font-size: 0.82rem;
      font-weight: 700;
      text-transform: uppercase;
    }

    #expense-list {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .expense {
      padding: 12px;
      background: #fff;
      border: 1px solid #d9e0e7;
      border-radius: 7px;
    }

    .expense-amount {
      font-weight: 750;
    }

    .expense-category {
      text-transform: capitalize;
    }

    .expense-note {
      min-width: 0;
      color: #52606d;
      overflow-wrap: anywhere;
    }

    .exp-del {
      min-height: 34px;
      padding: 6px 11px;
      color: #b42318;
      font-weight: 700;
      background: #fff;
      border: 1px solid #f0b5ae;
      border-radius: 5px;
      cursor: pointer;
    }

    .exp-del:hover {
      color: #fff;
      background: #b42318;
      border-color: #b42318;
    }

    #empty-state {
      margin: 0;
      padding: 24px;
      color: #52606d;
      text-align: center;
      background: #f7f9fb;
      border: 1px dashed #b8c2cc;
      border-radius: 7px;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 760px) {
      body {
        padding: 14px;
      }

      .form-grid,
      .filter-grid,
      .summary {
        grid-template-columns: 1fr;
      }

      .list-header {
        display: none;
      }

      .expense {
        grid-template-columns: 1fr 1fr;
      }

      .expense-note {
        grid-column: 1 / -1;
      }

      .exp-del {
        justify-self: start;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Personal Expense Tracker</h1>

    <section class="panel" aria-labelledby="entry-heading">
      <h2 id="entry-heading">Add an expense</h2>

      <form id="expense-form" novalidate>
        <div class="form-grid">
          <div class="field">
            <label for="amount">Amount</label>
            <input id="amount" name="amount" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00">
          </div>

          <div class="field">
            <label for="category">Category</label>
            <select id="category" name="category">
              <option value="groceries">Groceries</option>
              <option value="transport">Transport</option>
              <option value="bills">Bills</option>
              <option value="fun">Fun</option>
            </select>
          </div>

          <div class="field">
            <label for="date">Date</label>
            <input id="date" name="date" type="date">
          </div>

          <div class="field">
            <label for="note">Note (optional)</label>
            <input id="note" name="note" type="text" maxlength="160" placeholder="What was this for?">
          </div>

          <div class="field full">
            <button id="add-expense" type="submit">Add expense</button>
          </div>
        </div>

        <p id="form-error" role="alert" aria-live="polite"></p>
      </form>
    </section>

    <section class="panel" aria-labelledby="filter-heading">
      <h2 id="filter-heading">Filters</h2>

      <div class="filter-grid">
        <div class="field">
          <label for="filter-category">Category</label>
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </div>

        <div class="field">
          <label for="filter-from">From date</label>
          <input id="filter-from" type="date">
        </div>

        <div class="field">
          <label for="filter-to">To date</label>
          <input id="filter-to" type="date">
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Visible expense summary</h2>

      <div class="summary">
        <div class="summary-item">
          <span class="summary-label">Total</span>
          <span id="total">0.00</span>
        </div>

        <div class="summary-item">
          <span class="summary-label">Groceries</span>
          <span class="cat-total" data-cat="groceries">Groceries: 0.00</span>
        </div>

        <div class="summary-item">
          <span class="summary-label">Transport</span>
          <span class="cat-total" data-cat="transport">Transport: 0.00</span>
        </div>

        <div class="summary-item">
          <span class="summary-label">Bills</span>
          <span class="cat-total" data-cat="bills">Bills: 0.00</span>
        </div>

        <div class="summary-item">
          <span class="summary-label">Fun</span>
          <span class="cat-total" data-cat="fun">Fun: 0.00</span>
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="list-heading">
      <h2 id="list-heading">Expenses</h2>

      <div class="list-header" aria-hidden="true">
        <span>Amount</span>
        <span>Category</span>
        <span>Date</span>
        <span>Note</span>
        <span>Action</span>
      </div>

      <div id="expense-list"></div>
      <p id="empty-state">No expenses to show.</p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const STORAGE_KEY = "personal-expense-tracker-expenses";
      const categories = ["groceries", "transport", "bills", "fun"];

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const formError = document.getElementById("form-error");

      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");

      const expenseList = document.getElementById("expense-list");
      const emptyState = document.getElementById("empty-state");
      const totalElement = document.getElementById("total");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (!Array.isArray(saved)) return [];

          return saved.filter((expense) => {
            return expense &&
              typeof expense.id === "string" &&
              Number.isFinite(Number(expense.amount)) &&
              Number(expense.amount) > 0 &&
              categories.includes(expense.category) &&
              typeof expense.date === "string" &&
              expense.date.length > 0;
          }).map((expense) => ({
            id: expense.id,
            amount: Number(expense.amount),
            category: expense.category,
            date: expense.date,
            note: typeof expense.note === "string" ? expense.note : ""
          }));
        } catch (error) {
          return [];
        }
      }

      function saveExpenses() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
        } catch (error) {
          // The tracker remains usable for the current session if storage fails.
        }
      }

      function makeId() {
        return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2);
      }

      function formatAmount(value) {
        return Number(value).toFixed(2);
      }

      function createExpenseRow(expense) {
        const row = document.createElement("div");
        row.className = "expense";
        row.dataset.id = expense.id;
        row.dataset.category = expense.category;
        row.dataset.date = expense.date;
        row.dataset.amount = String(expense.amount);

        const amount = document.createElement("span");
        amount.className = "expense-amount";
        amount.textContent = formatAmount(expense.amount);

        const category = document.createElement("span");
        category.className = "expense-category";
        category.textContent = expense.category;

        const date = document.createElement("time");
        date.className = "expense-date";
        date.dateTime = expense.date;
        date.textContent = expense.date;

        const note = document.createElement("span");
        note.className = "expense-note";
        note.textContent = expense.note || "—";

        const deleteButton = document.createElement("button");
        deleteButton.type = "button";
        deleteButton.className = "exp-del";
        deleteButton.textContent = "Delete";
        deleteButton.setAttribute("aria-label", "Delete expense");

        row.append(amount, category, date, note, deleteButton);
        return row;
      }

      function renderExpenses() {
        expenseList.replaceChildren();

        expenses.forEach((expense) => {
          expenseList.appendChild(createExpenseRow(expense));
        });

        applyFilters();
      }

      function applyFilters() {
        const selectedCategory = filterCategory.value;
        const fromDate = filterFrom.value;
        const toDate = filterTo.value;

        const totals = {
          groceries: 0,
          transport: 0,
          bills: 0,
          fun: 0
        };

        let visibleTotal = 0;
        let visibleCount = 0;

        expenseList.querySelectorAll(".expense").forEach((row) => {
          const matchesCategory =
            selectedCategory === "all" ||
            row.dataset.category === selectedCategory;

          const matchesFrom =
            !fromDate ||
            row.dataset.date >= fromDate;

          const matchesTo =
            !toDate ||
            row.dataset.date <= toDate;

          const isVisible = matchesCategory && matchesFrom && matchesTo;
          row.hidden = !isVisible;

          if (isVisible) {
            const amount = Number(row.dataset.amount);
            visibleTotal += amount;
            totals[row.dataset.category] += amount;
            visibleCount += 1;
          }
        });

        totalElement.textContent = formatAmount(visibleTotal);

        categories.forEach((category) => {
          const element = document.querySelector(
            '.cat-total[data-cat="' + category + '"]'
          );
          const label = category.charAt(0).toUpperCase() + category.slice(1);
          element.textContent = label + ": " + formatAmount(totals[category]);
        });

        emptyState.hidden = visibleCount !== 0;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const date = dateInput.value;

        if (rawAmount === "" || !Number.isFinite(amount) || amount <= 0) {
          formError.textContent = "Enter a valid amount greater than zero.";
          return;
        }

        if (!date) {
          formError.textContent = "Select a date for the expense.";
          return;
        }

        expenses.unshift({
          id: makeId(),
          amount,
          category: categoryInput.value,
          date,
          note: noteInput.value.trim()
        });

        saveExpenses();
        formError.textContent = "";
        amountInput.value = "";
        noteInput.value = "";
        renderExpenses();
        amountInput.focus();
      });

      expenseList.addEventListener("click", (event) => {
        const deleteButton = event.target.closest(".exp-del");
        if (!deleteButton) return;

        const row = deleteButton.closest(".expense");
        expenses = expenses.filter((expense) => expense.id !== row.dataset.id);
        saveExpenses();
        renderExpenses();
      });

      filterCategory.addEventListener("change", applyFilters);
      filterFrom.addEventListener("input", applyFilters);
      filterFrom.addEventListener("change", applyFilters);
      filterTo.addEventListener("input", applyFilters);
      filterTo.addEventListener("change", applyFilters);

      renderExpenses();
    })();
  </script>
</body>
</html>
